-- CASE Network mathematics standards, and the map from them to Propel's
-- chapters for Classes 1-8. Generated by scripts/learning-commons/build-seed.mjs
-- from data fetched on 22 Sep 2026 — do not hand-edit; re-run the generator.
--
-- Three kinds of row, and they are not equally certain:
--
--   learning_standards / _components / _prereqs are PUBLISHED FACTS, copied
--   as the CASE Network states them.
--
--   textbook_chapter_standards is OUR JUDGEMENT about which standard a Propel
--   chapter teaches, and it arrives unreviewed. Nothing in the app can read it
--   until a teacher sets reviewed_at (the learning_chapter_outcomes view).
--
-- Chapters are mapped by WHAT THEY TEACH. Propel runs ahead of CCSS in places
-- — Class 5 sets profit and loss, which CCSS places in grade 7 — so the grade
-- numbers deliberately do not line up, and nothing joins on them.
--
-- Three chapters are deliberately left unmapped, and a re-run will leave them
-- unmapped again:
--   Class 1 ch12 Money, Class 2 ch11 Money — the only CCSS money standard
--     (2.MD.C.8) is written in dollars, quarters, dimes, nickels and pennies.
--     A rupee chapter must not inherit American currency as its outcome.
--   Class 8 ch3 A Story of Numbers — a history chapter; CCSS has no counterpart.
--
-- Learning components are seeded for the standards taught in Classes 3-8. The
-- components published for Classes 1-2 are representation micro-skills
-- ("represent addition with fingers", "…with sounds") which make poor question
-- targets; those standards carry their statement and nothing else.

begin;

-- 174 standards: 119 mapped to a chapter, 55 held only because something maps to them as a prerequisite.
insert into public.learning_standards (case_uuid, code, framework, subject, statement, grade_low, grade_high) values
  ('6b9e8c53-d7cc-11e8-824f-0242ac160002', 'K.CC.A.3', 'ccss-math', 'Mathematics', 'Write numbers from 0 to 20. Represent a number of objects with a written numeral 0-20 (with 0 representing a count of no objects).', 0, 0),
  ('6b9f2c57-d7cc-11e8-824f-0242ac160002', 'K.CC.B.4', 'ccss-math', 'Mathematics', 'Understand the relationship between numbers and quantities; connect counting to cardinality.', 0, 0),
  ('6ba08e06-d7cc-11e8-824f-0242ac160002', 'K.CC.C.7', 'ccss-math', 'Mathematics', 'Compare two numbers between 1 and 10 presented as written numerals.', 0, 0),
  ('6b9c9896-d7cc-11e8-824f-0242ac160002', 'K.G.A.1', 'ccss-math', 'Mathematics', 'Describe objects in the environment using names of shapes, and describe the relative positions of these objects using terms such as above, below, beside, in front of, behind, and next to.', 0, 0),
  ('6b9f2ef8-d7cc-11e8-824f-0242ac160002', 'K.G.B.4', 'ccss-math', 'Mathematics', 'Analyze and compare two- and three-dimensional shapes, in different sizes and orientations, using informal language to describe their similarities, differences, parts (e.g., number of sides and vertices/"corners") and other attributes (e.g., having sides of equal length).', 0, 0),
  ('6b9c9af3-d7cc-11e8-824f-0242ac160002', 'K.MD.A.1', 'ccss-math', 'Mathematics', 'Describe measurable attributes of objects, such as length or weight. Describe several measurable attributes of a single object.', 0, 0),
  ('6b9dce41-d7cc-11e8-824f-0242ac160002', 'K.MD.A.2', 'ccss-math', 'Mathematics', 'Directly compare two objects with a measurable attribute in common, to see which object has "more of"/"less of" the attribute, and describe the difference.', 0, 0),
  ('6b9e9181-d7cc-11e8-824f-0242ac160002', 'K.MD.B.3', 'ccss-math', 'Mathematics', 'Classify objects into given categories; count the numbers of objects in each category and sort the categories by count.', 0, 0),
  ('6b9ca104-d7cc-11e8-824f-0242ac160002', 'K.OA.A.1', 'ccss-math', 'Mathematics', 'Represent addition and subtraction with objects, fingers, mental images, drawings, sounds (e.g., claps), acting out situations, verbal explanations, expressions, or equations.', 0, 0),
  ('6b9dd100-d7cc-11e8-824f-0242ac160002', 'K.OA.A.2', 'ccss-math', 'Mathematics', 'Solve addition and subtraction word problems, and add and subtract within 10, e.g., by using objects or drawings to represent the problem.', 0, 0),
  ('6b9bd535-d7cc-11e8-824f-0242ac160002', '1.G.A.1', 'ccss-math', 'Mathematics', 'Distinguish between defining attributes (e.g., triangles are closed and three-sided) versus non-defining attributes (e.g., color, orientation, overall size); build and draw shapes to possess defining attributes.', 1, 1),
  ('6b9d1dd5-d7cc-11e8-824f-0242ac160002', '1.G.A.2', 'ccss-math', 'Mathematics', 'Compose two-dimensional shapes (rectangles, squares, trapezoids, triangles, half-circles, and quarter-circles) or three-dimensional shapes (cubes, right rectangular prisms, right circular cones, and right circular cylinders) to create a composite shape, and compose new shapes from the composite shape.', 1, 1),
  ('6b9bd85b-d7cc-11e8-824f-0242ac160002', '1.MD.A.1', 'ccss-math', 'Mathematics', 'Order three objects by length; compare the lengths of two objects indirectly by using a third object.', 1, 1),
  ('6b9d205c-d7cc-11e8-824f-0242ac160002', '1.MD.A.2', 'ccss-math', 'Mathematics', 'Express the length of an object as a whole number of length units, by laying multiple copies of a shorter object (the length unit) end to end; understand that the length measurement of an object is the number of same-size length units that span it with no gaps or overlaps.', 1, 1),
  ('6b9e0b6c-d7cc-11e8-824f-0242ac160002', '1.MD.B.3', 'ccss-math', 'Mathematics', 'Tell and write time in hours and half-hours using analog and digital clocks.', 1, 1),
  ('6b9eb642-d7cc-11e8-824f-0242ac160002', '1.MD.C.4', 'ccss-math', 'Mathematics', 'Organize, represent, and interpret data with up to three categories; ask and answer questions about the total number of data points, how many in each category, and how many more or less are in one category than in another.', 1, 1),
  ('6b9bdbaf-d7cc-11e8-824f-0242ac160002', '1.NBT.A.1', 'ccss-math', 'Mathematics', 'Count to 120, starting at any number less than 120. In this range, read and write numerals and represent a number of objects with a written numeral.', 1, 1),
  ('6b9d22e5-d7cc-11e8-824f-0242ac160002', '1.NBT.B.2', 'ccss-math', 'Mathematics', 'Understand that the two digits of a two-digit number represent amounts of tens and ones.', 1, 1),
  ('6b9eb89a-d7cc-11e8-824f-0242ac160002', '1.NBT.C.4', 'ccss-math', 'Mathematics', 'Add within 100, including adding a two-digit number and a one-digit number, and adding a two-digit number and a multiple of 10, using concrete models or drawings and strategies based on place value, properties of operations, and/or the relationship between addition and subtraction; relate the strategy to a written method and explain the reasoning used. Understand that in adding two-digit numbers, one adds tens and tens, ones and ones; and sometimes it is necessary to compose a ten.', 1, 1),
  ('6b9fd080-d7cc-11e8-824f-0242ac160002', '1.NBT.C.6', 'ccss-math', 'Mathematics', 'Subtract multiples of 10 in the range 10-90 from multiples of 10 in the range 10-90 (positive or zero differences), using concrete models or drawings and strategies based on place value, properties of operations, and/or the relationship between addition and subtraction; relate the strategy to a written method and explain the reasoning used.', 1, 1),
  ('6b9fd4e5-d7cc-11e8-824f-0242ac160002', '1.OA.C.6', 'ccss-math', 'Mathematics', 'Add and subtract within 20, demonstrating fluency for addition and subtraction within 10. Use strategies such as counting on; making ten; decomposing a number leading to a ten; using the relationship between addition and subtraction; and creating equivalent but easier or known sums.', 1, 1),
  ('6b9be213-d7cc-11e8-824f-0242ac160002', '2.G.A.1', 'ccss-math', 'Mathematics', 'Recognize and draw shapes having specified attributes, such as a given number of angles or a given number of equal faces. Identify triangles, quadrilaterals, pentagons, hexagons, and cubes.', 2, 2),
  ('6b9e11e8-d7cc-11e8-824f-0242ac160002', '2.G.A.3', 'ccss-math', 'Mathematics', 'Partition circles and rectangles into two, three, or four equal shares, describe the shares using the words halves, thirds, half of, a third of, etc., and describe the whole as two halves, three thirds, four fourths. Recognize that equal shares of identical wholes need not have the same shape.', 2, 2),
  ('6b9be543-d7cc-11e8-824f-0242ac160002', '2.MD.A.1', 'ccss-math', 'Mathematics', 'Measure the length of an object by selecting and using appropriate tools such as rulers, yardsticks, meter sticks, and measuring tapes.', 2, 2),
  ('6b9e1402-d7cc-11e8-824f-0242ac160002', '2.MD.A.3', 'ccss-math', 'Mathematics', 'Estimate lengths using units of inches, feet, centimeters, and meters.', 2, 2),
  ('6ba03dbb-d7cc-11e8-824f-0242ac160002', '2.MD.C.7', 'ccss-math', 'Mathematics', 'Tell and write time from analog and digital clocks to the nearest five minutes, using a.m. and p.m.', 2, 2),
  ('6b9ca5d9-d7cc-11e8-824f-0242ac160002', '2.MD.D.10', 'ccss-math', 'Mathematics', 'Draw a picture graph and a bar graph (with single-unit scale) to represent a data set with up to four categories. Solve simple put-together, take-apart, and compare problems using information presented in a bar graph.', 2, 2),
  ('6b9be86e-d7cc-11e8-824f-0242ac160002', '2.NBT.A.1', 'ccss-math', 'Mathematics', 'Understand that the three digits of a three-digit number represent amounts of hundreds, tens, and ones; e.g., 706 equals 7 hundreds, 0 tens, and 6 ones.', 2, 2),
  ('6b9d2e64-d7cc-11e8-824f-0242ac160002', '2.NBT.A.2', 'ccss-math', 'Mathematics', 'Count within 1000; skip-count by 5s, 10s, and 100s.', 2, 2),
  ('6b9e166e-d7cc-11e8-824f-0242ac160002', '2.NBT.A.3', 'ccss-math', 'Mathematics', 'Read and write numbers to 1000 using base-ten numerals, number names, and expanded form.', 2, 2),
  ('6b9ebf9b-d7cc-11e8-824f-0242ac160002', '2.NBT.A.4', 'ccss-math', 'Mathematics', 'Compare two three-digit numbers based on meanings of the hundreds, tens, and ones digits, using >, =, and < symbols to record the results of comparisons.', 2, 2),
  ('6b9f57e3-d7cc-11e8-824f-0242ac160002', '2.NBT.B.5', 'ccss-math', 'Mathematics', 'Fluently add and subtract within 100 using strategies based on place value, properties of operations, and/or the relationship between addition and subtraction.', 2, 2),
  ('6ba040da-d7cc-11e8-824f-0242ac160002', '2.NBT.B.7', 'ccss-math', 'Mathematics', 'Add and subtract within 1000, using concrete models or drawings and strategies based on place value, properties of operations, and/or the relationship between addition and subtraction; relate the strategy to a written method.', 2, 2),
  ('6b9e188a-d7cc-11e8-824f-0242ac160002', '2.OA.C.3', 'ccss-math', 'Mathematics', 'Determine whether a group of objects (up to 20) has an odd or even number of members, e.g., by pairing objects or counting them by 2s; write an equation to express an even number as a sum of two equal addends.', 2, 2),
  ('6b9ec21d-d7cc-11e8-824f-0242ac160002', '2.OA.C.4', 'ccss-math', 'Mathematics', 'Use addition to find the total number of objects arranged in rectangular arrays with up to 5 rows and up to 5 columns; write an equation to express the total as a sum of equal addends.', 2, 2),
  ('6b9beecd-d7cc-11e8-824f-0242ac160002', '3.G.A.1', 'ccss-math', 'Mathematics', 'Understand that shapes in different categories (e.g., rhombuses, rectangles, and others) may share attributes (e.g., having four sides), and that the shared attributes can define a larger category (e.g., quadrilaterals). Recognize rhombuses, rectangles, and squares as examples of quadrilaterals, and draw examples of quadrilaterals that do not belong to any of these subcategories.', 3, 3),
  ('6b9bf1fd-d7cc-11e8-824f-0242ac160002', '3.MD.A.1', 'ccss-math', 'Mathematics', 'Tell and write time to the nearest minute and measure time intervals in minutes. Solve word problems involving addition and subtraction of time intervals in minutes, e.g., by representing the problem on a number line diagram.', 3, 3),
  ('6b9d3655-d7cc-11e8-824f-0242ac160002', '3.MD.A.2', 'ccss-math', 'Mathematics', 'Measure and estimate liquid volumes and masses of objects using standard units of grams (g), kilograms (kg), and liters (l). Add, subtract, multiply, or divide to solve one-step word problems involving masses or volumes that are given in the same units.', 3, 3),
  ('6b9e1aec-d7cc-11e8-824f-0242ac160002', '3.MD.B.3', 'ccss-math', 'Mathematics', 'Draw a scaled picture graph and a scaled bar graph to represent a data set with several categories. Solve one- and two-step "how many more" and "how many less" problems using information presented in scaled bar graphs.', 3, 3),
  ('6ba04403-d7cc-11e8-824f-0242ac160002', '3.MD.C.7', 'ccss-math', 'Mathematics', 'Relate area to the operations of multiplication and addition.', 3, 3),
  ('6b9bf525-d7cc-11e8-824f-0242ac160002', '3.NBT.A.1', 'ccss-math', 'Mathematics', 'Use place value understanding to round whole numbers to the nearest 10 or 100.', 3, 3),
  ('6b9d3a38-d7cc-11e8-824f-0242ac160002', '3.NBT.A.2', 'ccss-math', 'Mathematics', 'Fluently add and subtract within 1000 using strategies and algorithms based on place value, properties of operations, and/or the relationship between addition and subtraction.', 3, 3),
  ('6b9e1e66-d7cc-11e8-824f-0242ac160002', '3.NBT.A.3', 'ccss-math', 'Mathematics', 'Multiply one-digit whole numbers by multiples of 10 in the range 10-90 using strategies based on place value and properties of operations.', 3, 3),
  ('6b9bf846-d7cc-11e8-824f-0242ac160002', '3.NF.A.1', 'ccss-math', 'Mathematics', 'Understand a fraction 1/b as the quantity formed by 1 part when a whole is partitioned into b equal parts; understand a fraction a/b as the quantity formed by a parts of size 1/b.', 3, 3),
  ('6b9bfb73-d7cc-11e8-824f-0242ac160002', '3.OA.A.1', 'ccss-math', 'Mathematics', 'Interpret products of whole numbers, e.g., interpret 5 x 7 as the total number of objects in 5 groups of 7 objects each.', 3, 3),
  ('6b9d430d-d7cc-11e8-824f-0242ac160002', '3.OA.A.2', 'ccss-math', 'Mathematics', 'Interpret whole-number quotients of whole numbers, e.g., interpret 56 / 8 as the number of objects in each share when 56 objects are partitioned equally into 8 shares, or as a number of shares when 56 objects are partitioned into equal shares of 8 objects each.', 3, 3),
  ('6b9fe0ba-d7cc-11e8-824f-0242ac160002', '3.OA.B.6', 'ccss-math', 'Mathematics', 'Understand division as an unknown-factor problem.', 3, 3),
  ('6ba0471b-d7cc-11e8-824f-0242ac160002', '3.OA.C.7', 'ccss-math', 'Mathematics', 'Fluently multiply and divide within 100, using strategies such as the relationship between multiplication and division or properties of operations. By the end of Grade 3, know from memory all products of two one-digit numbers.', 3, 3),
  ('6ba0e1df-d7cc-11e8-824f-0242ac160002', '3.OA.D.9', 'ccss-math', 'Mathematics', 'Identify arithmetic patterns (including patterns in the addition table or multiplication table), and explain them using properties of operations.', 3, 3),
  ('6b9bfea2-d7cc-11e8-824f-0242ac160002', '4.G.A.1', 'ccss-math', 'Mathematics', 'Draw points, lines, line segments, rays, angles (right, acute, obtuse), and perpendicular and parallel lines. Identify these in two-dimensional figures.', 4, 4),
  ('6b9d45b3-d7cc-11e8-824f-0242ac160002', '4.G.A.2', 'ccss-math', 'Mathematics', 'Classify two-dimensional figures based on the presence or absence of parallel or perpendicular lines, or the presence or absence of angles of a specified size. Recognize right triangles as a category, and identify right triangles.', 4, 4),
  ('6b9e25bb-d7cc-11e8-824f-0242ac160002', '4.G.A.3', 'ccss-math', 'Mathematics', 'Recognize a line of symmetry for a two-dimensional figure as a line across the figure such that the figure can be folded along the line into matching parts. Identify line-symmetric figures and draw lines of symmetry.', 4, 4),
  ('6b9c02b9-d7cc-11e8-824f-0242ac160002', '4.MD.A.1', 'ccss-math', 'Mathematics', 'Know relative sizes of measurement units within one system of units including km, m, cm; kg, g; l, ml; hr, min, sec. Within a single system of measurement, express measurements in a larger unit in terms of a smaller unit. Record measurement equivalents in a two column table.', 4, 4),
  ('6b9d484a-d7cc-11e8-824f-0242ac160002', '4.MD.A.2', 'ccss-math', 'Mathematics', 'Use the four operations to solve word problems involving distances, intervals of time, liquid volumes, masses of objects, and money, including problems involving simple fractions or decimals, and problems that require expressing measurements given in a larger unit in terms of a smaller unit.', 4, 4),
  ('6b9e283e-d7cc-11e8-824f-0242ac160002', '4.MD.A.3', 'ccss-math', 'Mathematics', 'Apply the area and perimeter formulas for rectangles in real world and mathematical problems.', 4, 4),
  ('6b9fe3ab-d7cc-11e8-824f-0242ac160002', '4.MD.C.6', 'ccss-math', 'Mathematics', 'Measure angles in whole-number degrees using a protractor. Sketch angles of specified measure.', 4, 4),
  ('6b9c0660-d7cc-11e8-824f-0242ac160002', '4.NBT.A.1', 'ccss-math', 'Mathematics', 'Recognize that in a multi-digit whole number, a digit in one place represents ten times what it represents in the place to its right.', 4, 4),
  ('6b9d4b33-d7cc-11e8-824f-0242ac160002', '4.NBT.A.2', 'ccss-math', 'Mathematics', 'Read and write multi-digit whole numbers using base-ten numerals, number names, and expanded form. Compare two multi-digit numbers based on meanings of the digits in each place, using >, =, and < symbols to record the results of comparisons.', 4, 4),
  ('6b9e2a5e-d7cc-11e8-824f-0242ac160002', '4.NBT.A.3', 'ccss-math', 'Mathematics', 'Use place value understanding to round multi-digit whole numbers to any place.', 4, 4),
  ('6b9ecb67-d7cc-11e8-824f-0242ac160002', '4.NBT.B.4', 'ccss-math', 'Mathematics', 'Fluently add and subtract multi-digit whole numbers using the standard algorithm.', 4, 4),
  ('6b9f62c1-d7cc-11e8-824f-0242ac160002', '4.NBT.B.5', 'ccss-math', 'Mathematics', 'Multiply a whole number of up to four digits by a one-digit whole number, and multiply two two-digit numbers, using strategies based on place value and the properties of operations. Illustrate and explain the calculation by using equations, rectangular arrays, and/or area models.', 4, 4),
  ('6b9fe69c-d7cc-11e8-824f-0242ac160002', '4.NBT.B.6', 'ccss-math', 'Mathematics', 'Find whole-number quotients and remainders with up to four-digit dividends and one-digit divisors, using strategies based on place value, the properties of operations, and/or the relationship between multiplication and division.', 4, 4),
  ('6b9c09e2-d7cc-11e8-824f-0242ac160002', '4.NF.A.1', 'ccss-math', 'Mathematics', 'Explain why a fraction a/b is equivalent to a fraction (n x a)/(n x b) by using visual fraction models, with attention to how the number and size of the parts differ even though the two fractions themselves are the same size. Use this principle to recognize and generate equivalent fractions.', 4, 4),
  ('6b9d4e66-d7cc-11e8-824f-0242ac160002', '4.NF.A.2', 'ccss-math', 'Mathematics', 'Compare two fractions with different numerators and different denominators, e.g., by creating common denominators or numerators, or by comparing to a benchmark fraction such as 1/2. Recognize that comparisons are valid only when the two fractions refer to the same whole.', 4, 4),
  ('6b9e2c7a-d7cc-11e8-824f-0242ac160002', '4.NF.B.3', 'ccss-math', 'Mathematics', 'Understand a fraction a/b with a > 1 as a sum of fractions 1/b.', 4, 4),
  ('6b9fea01-d7cc-11e8-824f-0242ac160002', '4.NF.C.6', 'ccss-math', 'Mathematics', 'Use decimal notation for fractions with denominators 10 or 100.', 4, 4),
  ('6ba04da6-d7cc-11e8-824f-0242ac160002', '4.NF.C.7', 'ccss-math', 'Mathematics', 'Compare two decimals to hundredths by reasoning about their size. Recognize that comparisons are valid only when the two decimals refer to the same whole.', 4, 4),
  ('6b9ed00e-d7cc-11e8-824f-0242ac160002', '4.OA.B.4', 'ccss-math', 'Mathematics', 'Find all factor pairs for a whole number in the range 1-100. Recognize that a whole number is a multiple of each of its factors. Determine whether a given whole number in the range 1-100 is prime or composite.', 4, 4),
  ('6b9f6853-d7cc-11e8-824f-0242ac160002', '4.OA.C.5', 'ccss-math', 'Mathematics', 'Generate a number or shape pattern that follows a given rule. Identify apparent features of the pattern that were not explicit in the rule itself.', 4, 4),
  ('6b9e30b9-d7cc-11e8-824f-0242ac160002', '5.G.B.3', 'ccss-math', 'Mathematics', 'Understand that attributes belonging to a category of two-dimensional figures also belong to all subcategories of that category.', 5, 5),
  ('6b9c13e2-d7cc-11e8-824f-0242ac160002', '5.MD.A.1', 'ccss-math', 'Mathematics', 'Convert among different-sized standard measurement units within a given measurement system (e.g., convert 5 cm to 0.05 m), and use these conversions in solving multi-step, real world problems.', 5, 5),
  ('6b9e32dc-d7cc-11e8-824f-0242ac160002', '5.MD.C.3', 'ccss-math', 'Mathematics', 'Recognize volume as an attribute of solid figures and understand concepts of volume measurement.', 5, 5),
  ('6b9f6b11-d7cc-11e8-824f-0242ac160002', '5.MD.C.5', 'ccss-math', 'Mathematics', 'Relate volume to the operations of multiplication and addition and solve real world and mathematical problems involving volume.', 5, 5),
  ('6b9e34fb-d7cc-11e8-824f-0242ac160002', '5.NBT.A.3', 'ccss-math', 'Mathematics', 'Read, write, and compare decimals to thousandths.', 5, 5),
  ('6b9f6e17-d7cc-11e8-824f-0242ac160002', '5.NBT.B.5', 'ccss-math', 'Mathematics', 'Fluently multiply multi-digit whole numbers using the standard algorithm.', 5, 5),
  ('6b9fed0a-d7cc-11e8-824f-0242ac160002', '5.NBT.B.6', 'ccss-math', 'Mathematics', 'Find whole-number quotients of whole numbers with up to four-digit dividends and two-digit divisors, using strategies based on place value, the properties of operations, and/or the relationship between multiplication and division.', 5, 5),
  ('6ba050ca-d7cc-11e8-824f-0242ac160002', '5.NBT.B.7', 'ccss-math', 'Mathematics', 'Add, subtract, multiply, and divide decimals to hundredths, using concrete models or drawings and strategies based on place value, properties of operations, and/or the relationship between addition and subtraction.', 5, 5),
  ('6b9c1a30-d7cc-11e8-824f-0242ac160002', '5.NF.A.1', 'ccss-math', 'Mathematics', 'Add and subtract fractions with unlike denominators (including mixed numbers) by replacing given fractions with equivalent fractions in such a way as to produce an equivalent sum or difference of fractions with like denominators.', 5, 5),
  ('6b9d5c8c-d7cc-11e8-824f-0242ac160002', '5.NF.A.2', 'ccss-math', 'Mathematics', 'Solve word problems involving addition and subtraction of fractions referring to the same whole, including cases of unlike denominators. Use benchmark fractions and number sense of fractions to estimate mentally and assess the reasonableness of answers.', 5, 5),
  ('6b9edad5-d7cc-11e8-824f-0242ac160002', '5.NF.B.4', 'ccss-math', 'Mathematics', 'Apply and extend previous understandings of multiplication to multiply a fraction or whole number by a fraction.', 5, 5),
  ('6b9c1d5d-d7cc-11e8-824f-0242ac160002', '5.OA.A.1', 'ccss-math', 'Mathematics', 'Use parentheses, brackets, or braces in numerical expressions, and evaluate expressions with these symbols.', 5, 5),
  ('6b9d5f43-d7cc-11e8-824f-0242ac160002', '5.OA.A.2', 'ccss-math', 'Mathematics', 'Write simple expressions that record calculations with numbers, and interpret numerical expressions without evaluating them.', 5, 5),
  ('6b9d6298-d7cc-11e8-824f-0242ac160002', '6.EE.A.2', 'ccss-math', 'Mathematics', 'Write, read, and evaluate expressions in which letters stand for numbers.', 6, 6),
  ('6b9e3b67-d7cc-11e8-824f-0242ac160002', '6.EE.A.3', 'ccss-math', 'Mathematics', 'Apply the properties of operations to generate equivalent expressions.', 6, 6),
  ('6b9ff310-d7cc-11e8-824f-0242ac160002', '6.EE.B.6', 'ccss-math', 'Mathematics', 'Use variables to represent numbers and write expressions when solving a real-world or mathematical problem; understand that a variable can represent an unknown number, or, depending on the purpose at hand, any number in a specified set.', 6, 6),
  ('6ba05715-d7cc-11e8-824f-0242ac160002', '6.EE.B.7', 'ccss-math', 'Mathematics', 'Solve real-world and mathematical problems by writing and solving equations of the form x + p = q and px = q for cases in which p, q and x are all nonnegative rational numbers.', 6, 6),
  ('6b9c2393-d7cc-11e8-824f-0242ac160002', '6.G.A.1', 'ccss-math', 'Mathematics', 'Find the area of right triangles, other triangles, special quadrilaterals, and polygons by composing into rectangles or decomposing into triangles and other shapes; apply these techniques in the context of solving real-world and mathematical problems.', 6, 6),
  ('6b9d6553-d7cc-11e8-824f-0242ac160002', '6.G.A.2', 'ccss-math', 'Mathematics', 'Find the volume of a right rectangular prism with fractional edge lengths by packing it with unit cubes of the appropriate unit fraction edge lengths. Apply the formulas V = lwh and V = bh to find volumes of right rectangular prisms in the context of solving real-world and mathematical problems.', 6, 6),
  ('6b9edfbc-d7cc-11e8-824f-0242ac160002', '6.G.A.4', 'ccss-math', 'Mathematics', 'Represent three-dimensional figures using nets made up of rectangles and triangles, and use the nets to find the surface area of these figures. Apply these techniques in the context of solving real-world and mathematical problems.', 6, 6),
  ('6b9c26ca-d7cc-11e8-824f-0242ac160002', '6.NS.A.1', 'ccss-math', 'Mathematics', 'Interpret and compute quotients of fractions, and solve word problems involving division of fractions by fractions, e.g., by using visual fraction models and equations to represent the problem.', 6, 6),
  ('6b9e3fc3-d7cc-11e8-824f-0242ac160002', '6.NS.B.3', 'ccss-math', 'Mathematics', 'Fluently add, subtract, multiply, and divide multi-digit decimals using the standard algorithm for each operation.', 6, 6),
  ('6b9ee241-d7cc-11e8-824f-0242ac160002', '6.NS.B.4', 'ccss-math', 'Mathematics', 'Find the greatest common factor of two whole numbers less than or equal to 100 and the least common multiple of two whole numbers less than or equal to 12. Use the distributive property to express a sum of two whole numbers with a common factor as a multiple of a sum of two whole numbers with no common factor.', 6, 6),
  ('6b9f77af-d7cc-11e8-824f-0242ac160002', '6.NS.C.5', 'ccss-math', 'Mathematics', 'Understand that positive and negative numbers are used together to describe quantities having opposite directions or values; use positive and negative numbers to represent quantities in real-world contexts, explaining the meaning of 0 in each situation.', 6, 6),
  ('6b9ff611-d7cc-11e8-824f-0242ac160002', '6.NS.C.6', 'ccss-math', 'Mathematics', 'Understand a rational number as a point on the number line. Extend number line diagrams and coordinate axes familiar from previous grades to represent points on the line and in the plane with negative number coordinates.', 6, 6),
  ('6ba05a42-d7cc-11e8-824f-0242ac160002', '6.NS.C.7', 'ccss-math', 'Mathematics', 'Understand ordering and absolute value of rational numbers.', 6, 6),
  ('6b9c2b26-d7cc-11e8-824f-0242ac160002', '6.RP.A.1', 'ccss-math', 'Mathematics', 'Understand the concept of a ratio and use ratio language to describe a ratio relationship between two quantities.', 6, 6),
  ('6b9e41ee-d7cc-11e8-824f-0242ac160002', '6.RP.A.3', 'ccss-math', 'Mathematics', 'Use ratio and rate reasoning to solve real-world and mathematical problems, e.g., by reasoning about tables of equivalent ratios, tape diagrams, double number line diagrams, or equations.', 6, 6),
  ('6b9e441c-d7cc-11e8-824f-0242ac160002', '6.SP.A.3', 'ccss-math', 'Mathematics', 'Recognize that a measure of center for a numerical data set summarizes all of its values with a single number, while a measure of variation describes how its values vary with a single number.', 6, 6),
  ('6b9ee4bb-d7cc-11e8-824f-0242ac160002', '6.SP.B.4', 'ccss-math', 'Mathematics', 'Display numerical data in plots on a number line, including dot plots, histograms, and box plots.', 6, 6),
  ('6b9f7a96-d7cc-11e8-824f-0242ac160002', '6.SP.B.5', 'ccss-math', 'Mathematics', 'Summarize numerical data sets in relation to their context.', 6, 6),
  ('6b9c313b-d7cc-11e8-824f-0242ac160002', '7.EE.A.1', 'ccss-math', 'Mathematics', 'Apply properties of operations as strategies to add, subtract, factor, and expand linear expressions with rational coefficients.', 7, 7),
  ('6b9ee71f-d7cc-11e8-824f-0242ac160002', '7.EE.B.4', 'ccss-math', 'Mathematics', 'Use variables to represent quantities in a real-world or mathematical problem, and construct simple equations and inequalities to solve problems by reasoning about the quantities.', 7, 7),
  ('6b9d73cd-d7cc-11e8-824f-0242ac160002', '7.G.A.2', 'ccss-math', 'Mathematics', 'Draw (freehand, with ruler and protractor, and with technology) geometric shapes with given conditions. Focus on constructing triangles from three measures of angles or sides, noticing when the conditions determine a unique triangle, more than one triangle, or no triangle.', 7, 7),
  ('6b9f7d68-d7cc-11e8-824f-0242ac160002', '7.G.B.5', 'ccss-math', 'Mathematics', 'Use facts about supplementary, complementary, vertical, and adjacent angles in a multi-step problem to write and solve simple equations for an unknown angle in a figure.', 7, 7),
  ('6b9ff914-d7cc-11e8-824f-0242ac160002', '7.G.B.6', 'ccss-math', 'Mathematics', 'Solve real-world and mathematical problems involving area, volume and surface area of two- and three-dimensional objects composed of triangles, quadrilaterals, polygons, cubes, and right prisms.', 7, 7),
  ('6b9c3725-d7cc-11e8-824f-0242ac160002', '7.NS.A.1', 'ccss-math', 'Mathematics', 'Apply and extend previous understandings of addition and subtraction to add and subtract rational numbers; represent addition and subtraction on a horizontal or vertical number line diagram.', 7, 7),
  ('6b9d769c-d7cc-11e8-824f-0242ac160002', '7.NS.A.2', 'ccss-math', 'Mathematics', 'Apply and extend previous understandings of multiplication and division and of fractions to multiply and divide rational numbers.', 7, 7),
  ('6b9d7951-d7cc-11e8-824f-0242ac160002', '7.RP.A.2', 'ccss-math', 'Mathematics', 'Recognize and represent proportional relationships between quantities.', 7, 7),
  ('6b9e4d0c-d7cc-11e8-824f-0242ac160002', '7.RP.A.3', 'ccss-math', 'Mathematics', 'Use proportional relationships to solve multistep ratio and percent problems.', 7, 7),
  ('6b9c4078-d7cc-11e8-824f-0242ac160002', '8.EE.A.1', 'ccss-math', 'Mathematics', 'Know and apply the properties of integer exponents to generate equivalent numerical expressions.', 8, 8),
  ('6b9d7eb3-d7cc-11e8-824f-0242ac160002', '8.EE.A.2', 'ccss-math', 'Mathematics', 'Use square root and cube root symbols to represent solutions to equations of the form x^2 = p and x^3 = p, where p is a positive rational number. Evaluate square roots of small perfect squares and cube roots of small perfect cubes.', 8, 8),
  ('6b9e5169-d7cc-11e8-824f-0242ac160002', '8.EE.A.3', 'ccss-math', 'Mathematics', 'Use numbers expressed in the form of a single digit times an integer power of 10 to estimate very large or very small quantities, and to express how many times as much one is than the other.', 8, 8),
  ('6b9ef0eb-d7cc-11e8-824f-0242ac160002', '8.EE.A.4', 'ccss-math', 'Mathematics', 'Perform operations with numbers expressed in scientific notation, including problems where both decimal and scientific notation are used. Use scientific notation and choose units of appropriate size for measurements of very large or very small quantities.', 8, 8),
  ('6b9f8362-d7cc-11e8-824f-0242ac160002', '8.EE.B.5', 'ccss-math', 'Mathematics', 'Graph proportional relationships, interpreting the unit rate as the slope of the graph. Compare two different proportional relationships represented in different ways.', 8, 8),
  ('6ba0609c-d7cc-11e8-824f-0242ac160002', '8.EE.C.7', 'ccss-math', 'Mathematics', 'Solve linear equations in one variable.', 8, 8),
  ('6b9c465b-d7cc-11e8-824f-0242ac160002', '8.G.A.1', 'ccss-math', 'Mathematics', 'Verify experimentally the properties of rotations, reflections, and translations.', 8, 8),
  ('6b9d8424-d7cc-11e8-824f-0242ac160002', '8.G.A.2', 'ccss-math', 'Mathematics', 'Understand that a two-dimensional figure is congruent to another if the second can be obtained from the first by a sequence of rotations, reflections, and translations; given two congruent figures, describe a sequence that exhibits the congruence between them.', 8, 8),
  ('6b9f89a0-d7cc-11e8-824f-0242ac160002', '8.G.A.5', 'ccss-math', 'Mathematics', 'Use informal arguments to establish facts about the angle sum and exterior angle of triangles, about the angles created when parallel lines are cut by a transversal, and the angle-angle criterion for similarity of triangles.', 8, 8),
  ('6b9c4a58-d7cc-11e8-824f-0242ac160002', '8.NS.A.1', 'ccss-math', 'Mathematics', 'Know that numbers that are not rational are called irrational. Understand informally that every number has a decimal expansion; for rational numbers show that the decimal expansion repeats eventually, and convert a decimal expansion which repeats eventually into a rational number.', 8, 8),
  ('6b9fc08e-d7cc-11e8-824f-0242ac160002', 'K.G.B.5', 'ccss-math', 'Mathematics', 'Model shapes in the world by building shapes from components (e.g., sticks and clay balls) and drawing shapes.', 0, 0),
  ('6ba030d6-d7cc-11e8-824f-0242ac160002', 'K.G.B.6', 'ccss-math', 'Mathematics', 'Compose simple shapes to form larger shapes.', 0, 0),
  ('6b9bdee1-d7cc-11e8-824f-0242ac160002', '1.OA.A.1', 'ccss-math', 'Mathematics', 'Use addition and subtraction within 20 to solve word problems involving situations of adding to, taking from, putting together, taking apart, and comparing, with unknowns in all positions.', 1, 1),
  ('6b9d25bb-d7cc-11e8-824f-0242ac160002', '1.OA.A.2', 'ccss-math', 'Mathematics', 'Solve word problems that call for addition of three whole numbers whose sum is less than or equal to 20.', 1, 1),
  ('6b9c9637-d7cc-11e8-824f-0242ac160002', 'K.CC.A.1', 'ccss-math', 'Mathematics', 'Count to 100 by ones and by tens.', 0, 0),
  ('6b9c9da7-d7cc-11e8-824f-0242ac160002', 'K.NBT.A.1', 'ccss-math', 'Mathematics', 'Compose and decompose numbers from 11 to 19 into ten ones and some further ones; understand that these numbers are composed of ten ones and one to nine further ones.', 0, 0),
  ('6b9e0fbe-d7cc-11e8-824f-0242ac160002', '1.OA.B.3', 'ccss-math', 'Mathematics', 'Apply properties of operations as strategies to add and subtract.', 1, 1),
  ('6b9e93c4-d7cc-11e8-824f-0242ac160002', 'K.OA.A.3', 'ccss-math', 'Mathematics', 'Decompose numbers less than or equal to 10 into pairs in more than one way, and record each decomposition by a drawing or equation.', 0, 0),
  ('6b9ebb03-d7cc-11e8-824f-0242ac160002', '1.OA.B.4', 'ccss-math', 'Mathematics', 'Understand subtraction as an unknown-addend problem.', 1, 1),
  ('6b9f318e-d7cc-11e8-824f-0242ac160002', 'K.OA.A.4', 'ccss-math', 'Mathematics', 'For any number from 1 to 9, find the number that makes 10 when added to the given number.', 0, 0),
  ('6b9f527f-d7cc-11e8-824f-0242ac160002', '1.OA.C.5', 'ccss-math', 'Mathematics', 'Relate counting to addition and subtraction (e.g., by counting on 2 to add 2).', 1, 1),
  ('6b9fc478-d7cc-11e8-824f-0242ac160002', 'K.OA.A.5', 'ccss-math', 'Mathematics', 'Fluently add and subtract within 5.', 0, 0),
  ('6b9d290b-d7cc-11e8-824f-0242ac160002', '2.G.A.2', 'ccss-math', 'Mathematics', 'Partition a rectangle into rows and columns of same-size squares and count to find the total number of them.', 2, 2),
  ('6b9e0945-d7cc-11e8-824f-0242ac160002', '1.G.A.3', 'ccss-math', 'Mathematics', 'Partition circles and rectangles into two and four equal shares, describe the shares using the words halves, fourths, and quarters. Understand that decomposing into more equal shares creates smaller shares.', 1, 1),
  ('6b9d30e1-d7cc-11e8-824f-0242ac160002', '2.OA.B.2', 'ccss-math', 'Mathematics', 'Fluently add and subtract within 20 using mental strategies. By end of Grade 2, know from memory all sums of two one-digit numbers.', 2, 2),
  ('6b9f4fd0-d7cc-11e8-824f-0242ac160002', '1.NBT.C.5', 'ccss-math', 'Mathematics', 'Given a two-digit number, mentally find 10 more or 10 less than the number, without having to count; explain the reasoning used.', 1, 1),
  ('6ba03a8f-d7cc-11e8-824f-0242ac160002', '1.OA.D.7', 'ccss-math', 'Mathematics', 'Understand the meaning of the equal sign, and determine if equations involving addition and subtraction are true or false.', 1, 1),
  ('6ba09eb5-d7cc-11e8-824f-0242ac160002', '2.NBT.B.8', 'ccss-math', 'Mathematics', 'Mentally add 10 or 100 to a given number 100-900, and mentally subtract 10 or 100 from a given number 100-900.', 2, 2),
  ('6b9f5d5a-d7cc-11e8-824f-0242ac160002', '3.OA.B.5', 'ccss-math', 'Mathematics', 'Apply properties of operations as strategies to multiply and divide.', 3, 3),
  ('6b9d2bdf-d7cc-11e8-824f-0242ac160002', '2.MD.A.2', 'ccss-math', 'Mathematics', 'Measure the length of an object twice, using length units of different lengths for the two measurements; describe how the two measurements relate to the size of the unit chosen.', 2, 2),
  ('6b9f6583-d7cc-11e8-824f-0242ac160002', '4.NF.C.5', 'ccss-math', 'Mathematics', 'Express a fraction with denominator 10 as an equivalent fraction with denominator 100, and use this technique to add two fractions with respective denominators 10 and 100.', 4, 4),
  ('6ba1136b-d7cc-11e8-824f-0242ac160002', '4.NF.B.3.a', 'ccss-math', 'Mathematics', 'Understand addition and subtraction of fractions as joining and separating parts referring to the same whole.', 4, 4),
  ('6ba18d83-d7cc-11e8-824f-0242ac160002', '4.NF.B.3.b', 'ccss-math', 'Mathematics', 'Decompose a fraction into a sum of fractions with the same denominator in more than one way, recording each decomposition by an equation.', 4, 4),
  ('6ba208b6-d7cc-11e8-824f-0242ac160002', '4.NF.B.3.c', 'ccss-math', 'Mathematics', 'Add and subtract mixed numbers with like denominators.', 4, 4),
  ('6ba20bca-d7cc-11e8-824f-0242ac160002', '4.NF.B.4.c', 'ccss-math', 'Mathematics', 'Solve word problems involving multiplication of a fraction by a whole number.', 4, 4),
  ('6b9ec6c0-d7cc-11e8-824f-0242ac160002', '3.OA.A.4', 'ccss-math', 'Mathematics', 'Determine the unknown whole number in a multiplication or division equation relating three whole numbers.', 3, 3),
  ('6ba0a209-d7cc-11e8-824f-0242ac160002', '3.MD.D.8', 'ccss-math', 'Mathematics', 'Solve real world and mathematical problems involving perimeters of polygons, including finding the perimeter given the side lengths and finding an unknown side length.', 3, 3),
  ('6ba1826d-d7cc-11e8-824f-0242ac160002', '3.MD.C.7.b', 'ccss-math', 'Mathematics', 'Multiply side lengths to find areas of rectangles with whole-number side lengths in the context of solving real world and mathematical problems.', 3, 3),
  ('6b9f6012-d7cc-11e8-824f-0242ac160002', '4.MD.C.5', 'ccss-math', 'Mathematics', 'Recognize angles as geometric shapes that are formed wherever two rays share a common endpoint, and understand concepts of angle measurement.', 4, 4),
  ('6b9d51bd-d7cc-11e8-824f-0242ac160002', '4.OA.A.2', 'ccss-math', 'Mathematics', 'Multiply or divide to solve word problems involving multiplicative comparison, distinguishing multiplicative comparison from additive comparison.', 4, 4),
  ('6b9e210d-d7cc-11e8-824f-0242ac160002', '3.NF.A.3', 'ccss-math', 'Mathematics', 'Explain equivalence of fractions in special cases, and compare fractions by reasoning about their size.', 3, 3),
  ('6b9f5a86-d7cc-11e8-824f-0242ac160002', '3.MD.C.5', 'ccss-math', 'Mathematics', 'Recognize area as an attribute of plane figures and understand concepts of area measurement.', 3, 3),
  ('6b9c1708-d7cc-11e8-824f-0242ac160002', '5.NBT.A.1', 'ccss-math', 'Mathematics', 'Recognize that in a multi-digit number, a digit in one place represents 10 times as much as it represents in the place to its right and 1/10 of what it represents in the place to its left.', 5, 5),
  ('6ba053e8-d7cc-11e8-824f-0242ac160002', '5.NF.B.7', 'ccss-math', 'Mathematics', 'Apply and extend previous understandings of division to divide unit fractions by whole numbers and whole numbers by unit fractions.', 5, 5),
  ('6ba25f3e-d7cc-11e8-824f-0242ac160002', '4.NF.B.3.d', 'ccss-math', 'Mathematics', 'Solve word problems involving addition and subtraction of fractions referring to the same whole and having like denominators.', 4, 4),
  ('6b9ecdc0-d7cc-11e8-824f-0242ac160002', '4.NF.B.4', 'ccss-math', 'Mathematics', 'Apply and extend previous understandings of multiplication to multiply a fraction by a whole number.', 4, 4),
  ('6b9c2095-d7cc-11e8-824f-0242ac160002', '6.EE.A.1', 'ccss-math', 'Mathematics', 'Write and evaluate numerical expressions involving whole-number exponents.', 6, 6),
  ('6b9e3939-d7cc-11e8-824f-0242ac160002', '5.OA.B.3', 'ccss-math', 'Mathematics', 'Generate two numerical patterns using two given rules. Identify apparent relationships between corresponding terms.', 5, 5),
  ('6ba11b29-d7cc-11e8-824f-0242ac160002', '5.MD.C.5.a', 'ccss-math', 'Mathematics', 'Find the volume of a right rectangular prism with whole-number side lengths by packing it with unit cubes, and show that the volume is the same as would be found by multiplying the edge lengths.', 5, 5),
  ('6ba1965f-d7cc-11e8-824f-0242ac160002', '5.MD.C.5.b', 'ccss-math', 'Mathematics', 'Apply the formulas V = l x w x h and V = b x h for rectangular prisms to find volumes of right rectangular prisms with whole-number edge lengths.', 5, 5),
  ('6b9d680b-d7cc-11e8-824f-0242ac160002', '6.NS.B.2', 'ccss-math', 'Mathematics', 'Fluently divide multi-digit numbers using the standard algorithm.', 6, 6),
  ('6b9f70d0-d7cc-11e8-824f-0242ac160002', '5.NF.B.5', 'ccss-math', 'Mathematics', 'Interpret multiplication as scaling (resizing).', 5, 5),
  ('6b9c2e34-d7cc-11e8-824f-0242ac160002', '6.SP.A.1', 'ccss-math', 'Mathematics', 'Recognize a statistical question as one that anticipates variability in the data related to the question and accounts for it in the answers.', 6, 6),
  ('6b9d6d44-d7cc-11e8-824f-0242ac160002', '6.SP.A.2', 'ccss-math', 'Mathematics', 'Understand that a set of data collected to answer a statistical question has a distribution which can be described by its center, spread, and overall shape.', 6, 6),
  ('6b9d5741-d7cc-11e8-824f-0242ac160002', '5.MD.B.2', 'ccss-math', 'Mathematics', 'Make a line plot to display a data set of measurements in fractions of a unit. Use operations on fractions for this grade to solve problems involving information presented in line plots.', 5, 5),
  ('6b9edd45-d7cc-11e8-824f-0242ac160002', '6.EE.A.4', 'ccss-math', 'Mathematics', 'Identify when two expressions are equivalent (i.e., when the two expressions name the same number regardless of which value is substituted into them).', 6, 6),
  ('6ba04a80-d7cc-11e8-824f-0242ac160002', '4.MD.C.7', 'ccss-math', 'Mathematics', 'Recognize angle measure as additive. When an angle is decomposed into non-overlapping parts, the angle measure of the whole is the sum of the angle measures of the parts.', 4, 4),
  ('6b9c3a21-d7cc-11e8-824f-0242ac160002', '7.RP.A.1', 'ccss-math', 'Mathematics', 'Compute unit rates associated with ratios of fractions, including ratios of lengths, areas and other quantities measured in like or different units.', 7, 7),
  ('6b9d6aa3-d7cc-11e8-824f-0242ac160002', '6.RP.A.2', 'ccss-math', 'Mathematics', 'Understand the concept of a unit rate a/b associated with a ratio a:b with b not equal to 0, and use rate language in the context of a ratio relationship.', 6, 6),
  ('6b9e4aa8-d7cc-11e8-824f-0242ac160002', '7.NS.A.3', 'ccss-math', 'Mathematics', 'Solve real-world and mathematical problems involving the four operations with rational numbers.', 7, 7),
  ('6b9f74c0-d7cc-11e8-824f-0242ac160002', '6.EE.B.5', 'ccss-math', 'Mathematics', 'Understand solving an equation or inequality as a process of answering a question: which values from a specified set, if any, make the equation or inequality true?', 6, 6),
  ('6b9d59e4-d7cc-11e8-824f-0242ac160002', '5.NBT.A.2', 'ccss-math', 'Mathematics', 'Explain patterns in the number of zeros of the product when multiplying a number by powers of 10, and explain patterns in the placement of the decimal point when a decimal is multiplied or divided by a power of 10.', 5, 5),
  ('6b9e464c-d7cc-11e8-824f-0242ac160002', '7.EE.B.3', 'ccss-math', 'Mathematics', 'Solve multi-step real-life and mathematical problems posed with positive and negative rational numbers in any form, using tools strategically.', 7, 7),
  ('6b9ef5f0-d7cc-11e8-824f-0242ac160002', '8.G.A.4', 'ccss-math', 'Mathematics', 'Understand that a two-dimensional figure is similar to another if the second can be obtained from the first by a sequence of rotations, reflections, translations, and dilations.', 8, 8),
  ('6ba2703e-d7cc-11e8-824f-0242ac160002', '7.NS.A.2.d', 'ccss-math', 'Mathematics', 'Convert a rational number to a decimal using long division; know that the decimal form of a rational number terminates in 0s or eventually repeats.', 7, 7)
on conflict (case_uuid) do update set
  code = excluded.code,
  statement = excluded.statement,
  grade_low = excluded.grade_low,
  grade_high = excluded.grade_high,
  fetched_at = now();

-- 324 learning components across 87 standards.
insert into public.learning_standard_components (case_uuid, component_id, description) values
  ('6b9bf846-d7cc-11e8-824f-0242ac160002', '0f80aa86-2c60-5a0f-bd85-7720345949d9', 'Identify a fraction a/b as the quantity formed by a parts of size 1/b (where b is 2, 3, 4, 6, or 8)'),
  ('6b9bf846-d7cc-11e8-824f-0242ac160002', '188fe970-4e1d-52c4-9f18-5e2fade05494', 'Identify a fraction 1/b as the quantity formed by 1 part when a whole is partitioned into b equal parts (where b is 2, 3, 4, 6, or 8)'),
  ('6b9fd4e5-d7cc-11e8-824f-0242ac160002', '690addcb-a06c-5fa1-a4d0-0ea9499b9340', 'Add within 20, using strategies such as counting on, making ten, and creating equivalent but easier known sums.'),
  ('6b9fd4e5-d7cc-11e8-824f-0242ac160002', 'a00966f2-bc3c-5b7d-9191-2a2f74f240e2', 'Fluently add within 10'),
  ('6b9fd4e5-d7cc-11e8-824f-0242ac160002', 'c7ac60b3-ba70-5087-9183-458ff0a5bed5', 'Fluently subtract within 10'),
  ('6b9fd4e5-d7cc-11e8-824f-0242ac160002', 'e1cb5730-1fdb-58cd-8a57-8e273e00dc9b', 'Subtract within 20, using strategies such as counting down, decomposing a number leading to a ten, and using the relationship between addition and subtraction.'),
